{"content":""""Service layer used by the HTTP handlers."""
from .model import PRIORITIES, Task
from .serialize import task_to_dict
from .store import Store

_PRIORITY_RANK = {p: i for i, p in enumerate(("high", "normal", "low"))}


def _priority_from_payload(payload: dict) -> str:
    if "priority" not in payload:
        return "normal"
    priority = str(payload["priority"])
    if priority not in PRIORITIES:
        raise ValueError("priority must be one of %s" % (", ".join(PRIORITIES),))
    return priority


def create_task(store: Store, payload: dict) -> dict:
    t = Task(id=store.next_id(), title=str(payload.get("title", "")),
             done=bool(payload.get("done", False)), priority=_priority_from_payload(payload))
    t.validate()
    store.tasks[t.id] = t
    store.save()
    return task_to_dict(t)


def update_task(store: Store, task_id: int, payload: dict) -> dict:
    t = store.tasks[task_id]
    if "title" in payload:
        t.title = str(payload["title"])
    if "done" in payload:
        t.done = bool(payload["done"])
    if "priority" in payload:
        t.priority = _priority_from_payload(payload)
    t.validate()
    store.save()
    return task_to_dict(t)


def list_tasks(store: Store, done: bool | None = None, priority: str | None = None,
               sort: str | None = None) -> list[dict]:
    ts = list(store.tasks.values())
    if priority is not None:
        if priority not in PRIORITIES:
            raise ValueError("priority must be one of %s" % (", ".join(PRIORITIES),))
        ts = [t for t in ts if t.priority == priority]
    if sort == "priority":
        ts.sort(key=lambda t: _PRIORITY_RANK[t.priority])
        ts.sort(key=lambda t: t.id)
    else:
        ts.sort(key=lambda t: t.id)
    if done is not None:
        ts = [t for t in ts if t.done == done]
    return [task_to_dict(t) for t in ts]
